import{R as t,e as i,f as r,U as o}from"./chunks/framework.ywem4qy5.js";const d=JSON.parse('{"title":"Maximizer","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/crm/maximizer.md","filePath":"integrations/crm/maximizer.md","lastUpdated":1775908585000}'),a={name:"integrations/crm/maximizer.md"};function n(s,e,l,m,h,g){return i(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="maximizer" tabindex="-1">Maximizer <a class="header-anchor" href="#maximizer" aria-label="Permalink to &quot;Maximizer&quot;">​</a></h1><p>Follow the below steps to connect to the Maximizer API.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>CRM</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select Maximizer as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-maximizer-api" tabindex="-1">Step 2. Connect to the Maximizer API <a class="header-anchor" href="#step-2-connect-to-the-maximizer-api" aria-label="Permalink to &quot;Step 2. Connect to the Maximizer API&quot;">​</a></h3><ol><li>Go to <a href="https://www.maximizer.com/support/crm-api/" target="_blank">Maximizer CRM API</a> and request access to their API.</li><li>When approved, you&#39;ll receive your details via email.</li><li>Enter your <strong>Username</strong> from Maximizer and paste in the <strong>Username</strong> field in Formie.</li><li>Enter your <strong>Password</strong> from Maximizer and paste in the <strong>Password</strong> field in Formie.</li><li>Copy the <strong>Web Access URL</strong> from Maximizer and paste in the <strong>Web Access URL</strong> field in Formie.</li><li>Copy the <strong>Database ID</strong> from Maximizer and paste in the <strong>Database ID</strong> field in Formie.</li><li>Copy the <strong>Vendor ID</strong> from Maximizer and paste in the <strong>Vendor ID</strong> field in Formie.</li><li>Copy the <strong>App Key</strong> from Maximizer and paste in the <strong>App Key</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Refresh</strong> button in the right-hand sidebar.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration and fill out all required fields.</li><li>Click <strong>Save</strong> to save the form.</li></ol>',10)])])}const p=t(a,[["render",n]]);export{d as __pageData,p as default};
